// KTongJX2.cpp:4132 THAY THAN STUB:
int LuaJX2_AskClientForNumber(Lua_State* L)   // AskClientForNumber(szCb, nMin, nMax, szPrompt)
{
	int nPlayerIndex = GetPlayerIndex(L);
	if (nPlayerIndex <= 0 || Lua_GetTopIndex(L) < 4) return 0;          // Linux: gettop > 3
	if (!Lua_IsString(L, 1) || !Lua_IsNumber(L, 2) || !Lua_IsNumber(L, 3) || !Lua_IsString(L, 4)) return 0;
	const char* szCb = Lua_ValueToString(L, 1);
	const char* szPrompt = Lua_ValueToString(L, 4);
	if (!szCb || !szCb[0]) return 0;
	KPlayer& p = Player[nPlayerIndex];
	p.m_dwNumberBoxId = Npc[p.m_nIndex].m_ActionScriptID;              // script NPC dang thoai (= Linux +0x5F9C)
	strncpy(p.m_szTaskExcuteFun, szCb, sizeof(p.m_szTaskExcuteFun) - 1); p.m_szTaskExcuteFun[sizeof(p.m_szTaskExcuteFun)-1] = 0;
	p.m_nWllsAskNumMin = (int)Lua_ValueToNumber(L, 2);
	p.m_nWllsAskNumMax = (int)Lua_ValueToNumber(L, 3);
	p.m_bWllsAskStrArg = 2;                                               // 2 = cho SO (1 = cho CHUOI, da co)
	S2C_INPUT_BOX nc; nc.ProtocolType = s2c_inputbox; nc.nType = 2;    // hop so co san cua client (GDCNI_OPEN_INPUT2)
	strncpy(nc.Value, szPrompt ? szPrompt : "", sizeof(nc.Value) - 1); nc.Value[sizeof(nc.Value)-1] = 0;   // toi da 31 byte!
	strncpy(nc.Value1, szCb, sizeof(nc.Value1) - 1); nc.Value1[sizeof(nc.Value1)-1] = 0;
	if (g_pServer && p.m_nNetConnectIdx != -1) g_pServer->PackDataToClient(p.m_nNetConnectIdx, &nc, sizeof(S2C_INPUT_BOX));
	return 0;
}

