// KJx2WarInfra.cpp:227 THAY:
int LuaSetPKFlag(Lua_State* L)
{
	int nPlayerIndex = GetPlayerIndex(L);
	if (nPlayerIndex <= 0 || Lua_GetTopIndex(L) < 1) return 0;
	int nFlag = (int)Lua_ValueToNumber(L, 1);
	if (nFlag < 0 || nFlag > 2) return 0;                // Linux: 0/1/2, khac thi thoat
	KPlayerPK& pk = Player[nPlayerIndex].m_cPK;           // KPlayer la friend cua KPlayerPK; neu khong truy cap duoc thi dung Player[].m_cPK.SetNormalPKState
	pk.SetNormalPKState((BYTE)nFlag, pk.GetLockPKState());   // giu nguyen khoa nhu Linux (khong ghi +8)
	return 0;
}

// KJx2WarInfra.cpp:234 THAY:
int LuaForbidChangePK(Lua_State* L)
{
	int nPlayerIndex = GetPlayerIndex(L);
	if (nPlayerIndex <= 0 || Lua_GetTopIndex(L) < 1) return 0;
