// KMission.cpp:338 THAY:
int g_MissionTimerCallBackFun(void * pOwner, char * szScriptFile)
{
	if (!pOwner || !szScriptFile || !szScriptFile[0]) return FALSE;
	KMission *pMission = (KMission*)pOwner;
	char szFun[20]; strcpy(szFun, "OnMissionTimer");
	char szLow[MAX_PATH]; g_StrCpyLen(szLow, szScriptFile, MAX_PATH); g_StrLower(szLow);
	KLuaScript* pS = (KLuaScript*)g_GetScript(szLow);
	if (pS && pS->m_LuaState)
	{
		int nTop = Lua_GetTopIndex(pS->m_LuaState);
		Lua_GetGlobal(pS->m_LuaState, "OnMissionTimer");
		BOOL bHas = lua_isfunction(pS->m_LuaState, Lua_GetTopIndex(pS->m_LuaState));
		lua_settop(pS->m_LuaState, nTop);
		if (!bHas) strcpy(szFun, "OnTimer");      // [BW/JX2] script Linux dat ten OnTimer
	}
	pMission->ExecuteScript(szScriptFile, szFun, 0);
	return 1;
}
// (cach B - khong dong engine: them cuoi bwtimer.lua va bwtotaltimer.lua dong 'OnMissionTimer = OnTimer' - lech byte so voi Linux)

